export type Item = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

export type QuoteStep = {
  op: "quote";
  items: Item[];
};

export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
};

export type ScenarioResult = {
  results: unknown[];
};

const PROCESSING_FEE = 5;

// Only the types the active tests exercise. Further types are added as
// their tests force them.
const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
};

// Applied as the exact fraction 11/10 rather than a 1.1 float multiplier:
// 100 * 1.1 is 110.00000000000001 in IEEE-754. The spec keeps intermediate
// amounts fractional and rounds only the final premium.
const addFirstInsuranceSurcharge = (amount: number): number =>
  (amount * 11) / 10;

const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];

const quotePremium = (step: QuoteStep): number => {
  const basePremium = step.items.reduce(
    (sum, item) => sum + basePremiumOf(item),
    0,
  );

  return addFirstInsuranceSurcharge(basePremium) + PROCESSING_FEE;
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
});

